#include "core.hpp"
#include <iostream>
using namespace atlas;
namespace {int checks=0;void expect(bool value,const char* message){++checks;if(!value)throw std::runtime_error(message);}template<class F>void cancelled(F fn){bool stopped=false;try{fn();}catch(const Cancelled&){stopped=true;}expect(stopped,"expected cooperative cancellation, not another failure");}}
int main(int argc,char**argv){try{
 if(argc!=2)throw Error("Provide one empty owned fixture directory");auto base=fs::absolute(path8(argv[1]));if(!fs::is_directory(base)||!fs::is_empty(base))throw Error("Fixture directory must exist and be empty");
 Store store(base/"collection");std::string cid;store.db.transaction([&]{cid=store.putChat("synthetic-cancel-account",{{"source_id","room"},{"title","Artificial cancellation"},{"kind","group"}});store.putItems(cid,J::array({{{"source_id","original"},{"kind","message"},{"text","original text"}}}));});
 int noParameterTicks=0;expect(store.db.rows("SELECT 7 AS n",J::array(),[&]{++noParameterTicks;})[0]["n"]==7&&noParameterTicks>0,"no-parameter query with Tick uses an explicit empty argument array");
 int rowTicks=0;cancelled([&]{store.db.rows("WITH RECURSIVE counter(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM counter WHERE n<50) SELECT n FROM counter",J::array(),[&]{if(++rowTicks==10)throw Cancelled();});});expect(rowTicks==10,"row enumeration cancels after materializing multiple rows");expect(store.db.rows("SELECT 1 AS n")[0]["n"]==1,"cancelled row query finalizes its statement and connection remains usable");
 auto original=store.db.rows("SELECT * FROM items");J incoming=J::array();for(int i=0;i<30;i++)incoming.push_back({{"source_id","new-"+std::to_string(i)},{"kind","message"},{"text",""},{"metadata",{{"content_omitted",true},{"omission_mode","skip_text"}}}});
 bool sawInsertion=false;cancelled([&]{store.db.transaction([&]{store.putItems(cid,incoming,[&]{if(store.db.rows("SELECT count(*) AS n FROM items")[0]["n"].get<int>()>1){auto inserted=store.db.rows("SELECT text,metadata FROM items WHERE source_id='new-0'");expect(inserted.size()==1&&inserted[0]["text"]==""&&J::parse(inserted[0]["metadata"].get<std::string>()).value("content_omitted",false),"actual staged row is a text-omitted anchor");sawInsertion=true;throw Cancelled();}});});});
 expect(sawInsertion,"cancellation happens after a real row insertion");expect(store.db.rows("SELECT * FROM items")==original,"cancelled batch rolls back all inserted rows and preserves existing content");expect(store.check({},false).empty(),"cancelled batch preserves valid relations");
 int ticks=0;cancelled([&]{store.identityProblems([&]{if(++ticks==5)throw Cancelled();});});expect(ticks==5,"identity traversal observes bounded ticks");
 ticks=0;cancelled([&]{store.check([&]{if(++ticks==5)throw Cancelled();},false);});expect(ticks==5,"integrity traversal observes bounded ticks");
 const auto page=exportHtml(store);auto before=digest(page).hash;ticks=0;cancelled([&]{exportHtml(store,[&]{if(++ticks==8)throw Cancelled();});});expect(digest(page).hash==before&&store.db.rows("SELECT * FROM items")==original,"cancelled export preserves prior page and all stored items");
 std::set<fs::path> priorGenerations;std::map<fs::path,std::string> oldChunks;for(const auto&e:fs::directory_iterator(store.root/"reader")){priorGenerations.insert(e.path());for(const auto&f:fs::directory_iterator(e.path()))if(f.is_regular_file())oldChunks[f.path()]=digest(f.path()).hash;}
 expect(!oldChunks.empty(),"old reader chunk preservation oracle is nonempty");
 bool reachedReader=false;cancelled([&]{exportHtml(store,[&]{for(const auto&e:fs::directory_iterator(store.root/"reader"))if(!priorGenerations.count(e.path()))for(const auto&f:fs::directory_iterator(e.path()))if(f.is_regular_file()&&f.path().extension()==".js"){reachedReader=true;throw Cancelled();}});});
 expect(reachedReader,"export cancellation occurs after new reader chunks were generated");expect(digest(page).hash==before,"cancel after chunk generation preserves previous index");for(const auto&[path,hash]:oldChunks)expect(fs::exists(path)&&digest(path).hash==hash,"cancel before index commit preserves old referenced chunks");
 // The lightweight Stop snapshot remains cancellable after doing useful reader work.
 std::set<fs::path> beforeQuick;for(const auto&e:fs::directory_iterator(store.root/"reader"))beforeQuick.insert(e.path());bool reachedQuick=false;
 cancelled([&]{exportHtml(store,[&]{for(const auto&e:fs::directory_iterator(store.root/"reader"))if(!beforeQuick.count(e.path()))for(const auto&f:fs::directory_iterator(e.path()))if(f.is_regular_file()&&f.path().extension()==".js"){reachedQuick=true;throw Cancelled();}},nullptr,false);});
 expect(reachedQuick&&digest(page).hash==before,"cancelling stop snapshot after chunk creation preserves previously published reader");for(const auto&[path,hash]:oldChunks)expect(fs::exists(path)&&digest(path).hash==hash,"cancelled stop snapshot preserves old page dependencies");
 // Metadata failure occurs before the final reader publication, preserving the old reader.
 auto metadataPath=store.root/"archive-info.json";auto oldMetadata=readText(metadataPath);fs::remove(metadataPath);privateDir(metadataPath);atomicText(metadataPath/"blocker","synthetic metadata failure");bool metadataFailed=false;try{exportHtml(store);}catch(const std::exception&){metadataFailed=true;}expect(metadataFailed,"metadata publication failure is reported before index commit");expect(digest(page).hash==before,"metadata failure does not publish a new index");for(const auto&[path,hash]:oldChunks)expect(fs::exists(path)&&digest(path).hash==hash,"metadata failure preserves old reader dependencies");fs::remove(metadataPath/"blocker");fs::remove(metadataPath);atomicText(metadataPath,oldMetadata);
 bool committedCleanup=false;std::string warning;auto published=exportHtml(store,[&]{if(digest(page).hash!=before){committedCleanup=true;throw Cancelled();}},&warning);expect(committedCleanup&&published==page&&!warning.empty(),"cancel after index commit returns success with cleanup warning");auto newMetadata=J::parse(readText(metadataPath));expect(readText(page).find(newMetadata["generation"].get<std::string>())!=std::string::npos,"successful publication metadata matches the new index generation");for(const auto&[path,hash]:oldChunks)expect(fs::exists(path)&&digest(path).hash==hash,"cancelled postcommit cleanup retains old reader chunks");
 std::string cleared="stale warning";exportHtml(store,{},&cleared);expect(cleared.empty(),"successful cleanup clears caller warning state");
 std::cout<<checks<<" cooperative Store cancellation checks passed\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
